/* ============================================================
   TESTIMONIALS
   ACF → PHP → window.WM_POPUP_DATA → CONFIG
   ============================================================ */
/*
 * Only use static testimonials if ACF has no testimonials.
 */
if (
    !Array.isArray(CONFIG.testimonials) ||
    CONFIG.testimonials.length === 0
) {
    CONFIG.testimonials = WM_STATIC_TESTIMONIALS;
}
const escH = s => {
    return String(s || "").replace(/[&<>"]/g,ch => ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;"
      }[ch])
    );

};
let qi = 0;
let qTimer = null;
/* ============================================================
   RENDER CURRENT TESTIMONIAL
   ============================================================ */
function renderQuote() {
    const T = CONFIG.testimonials;
    if (!Array.isArray(T) || !T.length) {
        return;
    }
    if (qi >= T.length) {
        qi = 0;
    }
    const t = T[qi];
    const q = $("#qText");
    const w = $("#qWho");
    if (!q || !w) {
      return;
    }
    q.classList.add("fade");
    w.classList.add("fade");
    setTimeout(() => {
        q.textContent = "“" + String(t.quote || "") + "”";
        const ini = String(t.name || "").split(/\s+/).filter(Boolean).map(s => s[0]).join("").slice(0, 2).toUpperCase();
        const imageUrl = String( t.image || "" ).trim();
        const avatar = imageUrl ? `
                <span class="av">
                    <img src="${escH(imageUrl)}" alt="${escH(t.name || "")}" loading="lazy">
                </span>
              `
            : `
                <span class="av">${escH(ini)}</span>
              `;
        const name = escH(String(t.name || "").trim());
        const role = String(t.role || "").trim();
        const roleHtml = role ? ` · ${escH(role)}` : "";

        w.innerHTML = `
            ${avatar}

            <span>
                <b>${name}</b>${roleHtml}
            </span>
        `;
        q.classList.remove("fade");
        w.classList.remove("fade");
    }, 350);
}
/* ============================================================
   AUTO ROTATION
   ============================================================ */
function startQuotes() {
    clearInterval(qTimer);
    if (!reduce && Array.isArray(CONFIG.testimonials) && CONFIG.testimonials.length > 1) {
        qTimer = setInterval(() => {
            qi = (qi + 1) % CONFIG.testimonials.length;
            renderQuote();
        }, 6000);
    }
}
/* ============================================================
   KEEP QUOTE AREA STABLE
   ============================================================ */
function fitQuote() {
    const fig = $(".quote");
    const q = $("#qText");
    if (!fig || !q) {
        return;
    }
    fig.style.minHeight = "";
    let max = 0;
    const keep = q.textContent;
    CONFIG.testimonials.forEach(t => {
        q.textContent = "“" + String(t.quote || "") + "”";
        max = Math.max(max,fig.offsetHeight);
    });
    q.textContent = keep;
    fig.style.minHeight = max + "px";
}
/* ============================================================
   INITIALIZE
   ============================================================ */
renderQuote();
startQuotes();

