const CHEV = '<svg class="chev" width="12" height="12" viewBox="0 0 12 12" fill="none"><path d="M3 4.5l3 3 3-3" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>';
root.querySelectorAll(".field, .wm-field").forEach(f => {
  const inp = f.querySelector("input:not([type=hidden]), select"); if (!inp) return;
  if (!f.querySelector("label")) {
    const nm = inp.name || "", map = {"first-name":"Full name","your-name":"Full name","full-name":"Full name","email":"Work email","your-email":"Work email","mobile":"Phone number","phonetext":"Phone number","phone":"Phone number","employee-size":"Company size","company-size":"Company size"};
    let txt = map[nm] || (inp.tagName === "INPUT" ? (inp.getAttribute("placeholder") || "") : "");
    if (txt.trim() && !f.classList.contains("cc") && !f.classList.contains("wm-cc")) {
      const req = /\*$/.test(txt.trim()) || inp.getAttribute("aria-required") === "true";
      const lb = document.createElement("label"); lb.innerHTML = txt.replace(/^\s*enter (your )?/i, "").replace(/\*$/, "").trim() + (req ? " <b>*</b>" : "");
      f.appendChild(lb);
    }
  }
  if (inp.tagName === "INPUT") inp.setAttribute("placeholder", " ");
  else {
    if (!f.querySelector(".chev")) f.insertAdjacentHTML("beforeend", CHEV);
    const o = inp.options[0]; if (o && o.value === "") { o.textContent = ""; o.hidden = true; }
  }
  const sync = () => f.classList.toggle("has-val", !!inp.value);
  inp.addEventListener("input", sync); inp.addEventListener("change", sync); sync();
});
const tel = root.querySelector("input[name=mobile], input[name=phonetext], input[type=tel]");
if (tel) tel.addEventListener("input", () => { tel.value = tel.value.replace(/\D/g, "").slice(0, 12); });
document.addEventListener("wpcf7reset", e => {
  if (!root.contains(e.target)) return;
  root.querySelectorAll(".field input, .field select, .wm-field input, .wm-field select").forEach(el => el.dispatchEvent(new Event("change")));
});
let optimistic = false;
function showDone(d){
  const name = (d["first-name"] || d["full-name"] || d["your-name"] || "").trim();
  $("#formView").hidden = true; $("#doneView").hidden = false; root.classList.add("wm-done");
  $("#doneTitle").textContent = name ? `Thank you, ${name.split(" ")[0]}!` : "Thank you!";
  $("#doneText").textContent = "Our team will contact you shortly to set up your WeekMate workspace.";
  const esc = s => String(s).replace(/[&<>"]/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[ch]));
  $("#summary").innerHTML = [["Name", name],["Work email", d["email"] || d["your-email"] || ""],["Phone", ((d["country-code"] || "") + " " + (d["phone"] || d["mobile"] || d["phonetext"] || "")).trim()],["Company size", (d["company-size"] || d["employee-size"] || "") + " employees"]]
    .map(([k, v]) => `<div><span>${k}</span><b>${esc(v)}</b></div>`).join("");
  /* phones: drop the keyboard and jump to the top so the thank-you screen is in view, then fire the confetti once the layout has settled */
  if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
  $("#panel").scrollTop = 0; $("#overlay").scrollTop = 0;
  requestAnimationFrame(() => { $("#overlay").scrollTop = 0; setTimeout(confetti, 150); });
}
/* instant result: show the thank-you screen as soon as the form passes a quick check, while CF7 sends in the background */
document.addEventListener("submit", e => {
  const form = e.target;
  if (!form.matches || !form.matches(".wpcf7-form") || !root.contains(form) || optimistic) return;
  const d = {}; new FormData(form).forEach((v, k) => { d[k] = String(v); });
  const nm = d["first-name"] || d["full-name"] || d["your-name"] || "", em = d["email"] || d["your-email"] || "", ph = d["phone"] || d["mobile"] || d["phonetext"] || "", sz = d["company-size"] || d["employee-size"] || "";
  const ok = nm.trim().length > 1 && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(em.trim()) && /^\d{7,15}$/.test(ph.trim()) && !!sz;
  if (!ok) return;
  optimistic = true; showDone(d);
}, true);
["wpcf7invalid", "wpcf7spam", "wpcf7mailfailed"].forEach(ev => document.addEventListener(ev, e => {
  if (!root.contains(e.target) || !optimistic) return;
  optimistic = false; $("#doneView").hidden = true; $("#formView").hidden = false; root.classList.remove("wm-done");
}));
document.addEventListener("wpcf7mailsent", e => {
  if (!root.contains(e.target)) return;
  if (!optimistic) { const d = {}; (e.detail.inputs || []).forEach(x => d[x.name] = x.value); showDone(d); }
  optimistic = false;
});
function confetti(){
  if (reduce) return;
  const c = $("#confetti"), panel = $("#panel"); c.hidden = false;
  const Wd = c.width = panel.clientWidth, H = c.height = panel.clientHeight, ctx = c.getContext("2d");
  const cols = ["#0B6BB8","#22B8EE","#085484","#F2A20C","#1E8E5A","#9BDCF6"];
  const P = Array.from({length:130}, () => ({x:Wd*.5, y:H*.22, vx:(Math.random()-.5)*11, vy:-Math.random()*10-3, s:Math.random()*6+4, r:Math.random()*6, vr:(Math.random()-.5)*.3, c:cols[Math.random()*cols.length|0]}));
  let f = 0;
  (function tick(){
    ctx.clearRect(0,0,Wd,H); f++;
    P.forEach(p => { p.vy += .32; p.vx *= .99; p.x += p.vx; p.y += p.vy; p.r += p.vr;
      ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.r); ctx.fillStyle = p.c; ctx.globalAlpha = Math.max(0, 1 - f/150); ctx.fillRect(-p.s/2,-p.s/4,p.s,p.s/2); ctx.restore(); });
    if (f < 150) requestAnimationFrame(tick); else c.hidden = true;
  })();
}

